import itertools

def get_good_paths_count(board, n):
    local_minima = []
    for r in range(n):
        for c in range(n):
            is_min = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    if board[nr][nc] < board[r][c]:
                        is_min = False
                        break
            if is_min:
                local_minima.append((r, c))

    memo = {}
    def count_paths(r, c):
        if (r, c) in memo:
            return memo[(r, c)]
        count = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if board[nr][nc] > board[r][c]:
                    count += count_paths(nr, nc)
        memo[(r, c)] = count
        return count

    total_paths = 0
    for r, c in local_minima:
        total_paths += count_paths(r, c)
    return total_paths

def solve_small(n):
    min_paths = float('inf')
    for p in itertools.permutations(range(1, n*n + 1)):
        board = [p[i*n:(i+1)*n] for i in range(n)]
        min_paths = min(min_paths, get_good_paths_count(board, n))
    return min_paths

